import React from 'react';

import queryString from 'query-string';
import { useLocation } from 'react-router-dom';

import { get } from '@helpers/httpClient';
import PohAlert from '@ui-kit/Alert';
import PohContainer from '@ui-kit/layout/Container';
import PohLoader from '@ui-kit/Loader';

const Registration = () => {
  const location = useLocation();
  const search = queryString.parse(location.search) || {};
  const [res, setRes] = React.useState(null);
  const [err, setErr] = React.useState(null);

  React.useEffect(() => {
    get('/auth/', search)
      .then((r) => {
        if (r.error) {
          setErr(r.error);
          return;
        }
        setRes(r);
        // eslint-disable-next-line
                opener && opener.postMessage(JSON.stringify(r), '*');
      })
      .catch((e) => {
        setErr(e?.message || 'something went wrong');
      });
  }, []);

  if (err) {
    return <PohAlert>{err}</PohAlert>;
  }

  if (res === null) {
    return <PohLoader />;
  }

  return (
    <PohContainer>
      <pre>{JSON.stringify(res, null, '  ')}</pre>
    </PohContainer>
  );
};

export default Registration;
